  for (const r of respostas) {
    if (!r || !r.resposta || r.resposta.error || !Array.isArray(r.resposta.results)) continue;
    algumaOk = true;
    for (const p of r.resposta.results) paginas.push({ crm: r.crm, url: p.url || urlNotion(p.id) });
